export function createChronosExtension(THREE,api){
 const COLORS={red:"#ff6b6b",orange:"#ff922b",yellow:"#ffd43b",green:"#63e6be",blue:"#75a7ff",purple:"#b197fc",pink:"#f783ac",cyan:"#66d9e8"};
 let group=null,content=null,controls=[],state=null,drag=null,eventObjects=[];
 const scalar=raw=>{const m=String(raw??"").trim().match(/^(-?\d{1,6})(?:-(\d{1,2})(?:-(\d{1,2}))?)?(?:T(\d{1,2})(?::(\d{1,2})(?::(\d{1,2}))?)?)?$/);if(!m)return NaN;return Number(m[1])+(Math.max(1,Number(m[2]||1))-1)/12+(Math.max(1,Number(m[3]||1))-1)/372+Number(m[4]||0)/8928+Number(m[5]||0)/535680+Number(m[6]||0)/32140800;};
 function parse(source){const events=[],flags={};for(const original of String(source??"").split(/\r?\n/)){const line=original.trim();if(!line||line.startsWith("#"))continue;if(line.startsWith(">")){const m=line.match(/^>\s*([A-Z]+)\s*(.*)$/i);if(m)flags[m[1].toUpperCase()]=m[2].trim();continue;}const m=line.match(/^([-@*=])\s*\[([^\]]+)\]\s*(?:#(red|orange|yellow|green|blue|purple|pink|cyan))?\s*(?:\{([^}]+)\})?\s*([^|]*?)(?:\s*\|\s*(.*))?$/i);if(!m)continue;const dates=m[2].split("~"),start=scalar(dates[0]),end=scalar(dates[1]??dates[0]);if(!Number.isFinite(start)||!Number.isFinite(end))continue;events.push({type:m[1],rawStart:dates[0].trim(),rawEnd:(dates[1]??dates[0]).trim(),start,end:Math.max(start,end),color:COLORS[(m[3]||"").toLowerCase()]||"#75a7ff",group:(m[4]||"Timeline").trim(),label:(m[5]||dates[0]).trim(),description:(m[6]||"").trim()});}const view=String(flags.DEFAULTVIEW||"").split("|").map(scalar),minimum=Math.min(...events.map(e=>e.start)),maximum=Math.max(...events.map(e=>e.end)),min=Number.isFinite(view[0])?view[0]:minimum,max=Number.isFinite(view[1])?view[1]:maximum;return{events,flags,min:Number.isFinite(min)?min:0,max:Number.isFinite(max)&&max>min?max:(Number.isFinite(min)?min+1:1),selected:-1};}
 function layout(s,width=900,compact=false){const groups=[...new Set(s.events.map(e=>e.group))],pad=compact?24:70,x=v=>pad+(v-s.min)/Math.max(1e-9,s.max-s.min)*(width-pad*2),assignments=new Map(),groupRows=new Map(),maxRows=compact?5:7;for(const name of groups){const ends=[];for(const item of s.events.map((event,index)=>({event,index})).filter(i=>i.event.group===name).sort((a,b)=>a.event.start-b.event.start)){const start=x(item.event.start),estimated=Math.min(compact?155:230,Math.max(50,item.event.label.length*(compact?7.2:9)));let row=ends.findIndex(end=>start>end+10);if(row<0&&ends.length<maxRows){row=ends.length;ends.push(-Infinity);}if(row<0)row=ends.indexOf(Math.min(...ends));ends[row]=Math.max(x(item.event.end),start+estimated);assignments.set(item.index,row);}groupRows.set(name,Math.max(1,ends.length));}return{groups,assignments,groupRows,totalRows:Math.max(1,[...groupRows.values()].reduce((a,b)=>a+b,0)),x,pad};}
 const yearLabel=v=>Math.round(v)<0?`${Math.abs(Math.round(v))} BCE`:String(Math.round(v));
 function clipped(ctx,text,width){let t=String(text);if(ctx.measureText(t).width<=width)return t;while(t.length>2&&ctx.measureText(t+"…").width>width)t=t.slice(0,-1);return t+"…";}
 function drawPreview(canvas,s){const ctx=canvas.getContext("2d",{alpha:true}),L=layout(s,canvas.width,true),top=34,bottom=24,rowH=(canvas.height-top-bottom)/L.totalRows;ctx.clearRect(0,0,canvas.width,canvas.height);ctx.fillStyle="rgba(7,14,25,.5)";ctx.fillRect(0,0,canvas.width,canvas.height);ctx.fillStyle="#f4f7ff";ctx.font="700 21px system-ui";ctx.textAlign="center";ctx.fillText(`Timeline · ${s.events.length} events`,canvas.width/2,24);let offset=0;for(const name of L.groups){const rows=L.groupRows.get(name)||1,groupTop=top+offset*rowH;for(const [index,e] of s.events.entries()){if(e.group!==name)continue;const row=L.assignments.get(index)||0,y=groupTop+(row+.5)*rowH,x1=L.x(e.start),x2=L.x(e.end);ctx.fillStyle=e.color;ctx.strokeStyle=e.color;if(e.type==="=" ){ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(x1,y-rowH*.32);ctx.lineTo(x1,y+rowH*.32);ctx.stroke();}else if(e.type==="@"||e.end>e.start+.00001)ctx.fillRect(x1,y-5,Math.max(5,x2-x1),10);else{ctx.beginPath();ctx.arc(x1,y,5,0,Math.PI*2);ctx.fill();}ctx.fillStyle="#eaf1ff";ctx.font="600 12px system-ui";ctx.textAlign="left";ctx.fillText(clipped(ctx,e.label,145),Math.min(x1+7,canvas.width-155),y-8);}offset+=rows;}ctx.fillStyle="#9fb0c8";ctx.font="12px system-ui";ctx.textAlign="left";ctx.fillText(yearLabel(s.min),8,canvas.height-7);ctx.textAlign="right";ctx.fillText(yearLabel(s.max),canvas.width-8,canvas.height-7);}
 async function renderBlocks(root){for(const el of root.querySelectorAll(".note-chronos")){let source=el.dataset.noteChronos||"";try{source=decodeURIComponent(source);}catch{}const parsed=parse(source),rows=layout(parsed,900,true).totalRows,canvas=document.createElement("canvas");canvas.width=900;canvas.height=Math.min(620,Math.max(150,62+rows*36));drawPreview(canvas,parsed);const img=document.createElement("img");img.className="note-chronos-image";img.alt=`Timeline with ${parsed.events.length} events`;img.decoding="async";img.src=canvas.toDataURL("image/webp",.8);el.replaceChildren(img);}}
 function textPlane(text,color="#fff",width=.13,height=.035,font=34,background=true){const ratio=THREE.MathUtils.clamp(width/Math.max(.001,height),1,8),canvas=document.createElement("canvas");canvas.height=128;canvas.width=Math.round(128*ratio);const actualWidth=height*ratio,ctx=canvas.getContext("2d");ctx.clearRect(0,0,canvas.width,canvas.height);if(background){ctx.fillStyle="rgba(5,10,18,.66)";ctx.beginPath();ctx.roundRect(4,10,canvas.width-8,108,25);ctx.fill();}ctx.fillStyle=color;ctx.font=`700 ${font}px system-ui`;ctx.textAlign="center";ctx.textBaseline="middle";ctx.fillText(text,canvas.width/2,64,canvas.width-28);const texture=new THREE.CanvasTexture(canvas);texture.colorSpace=THREE.SRGBColorSpace;texture.minFilter=THREE.LinearFilter;texture.generateMipmaps=false;const mesh=new THREE.Mesh(new THREE.PlaneGeometry(actualWidth,height),new THREE.MeshBasicMaterial({map:texture,transparent:true,depthTest:true,depthWrite:false,toneMapped:false}));mesh.raycast=()=>{};return mesh;}
 function addControl(action,x,label,color=0x75a7ff){const control=new THREE.Mesh(new THREE.CircleGeometry(.016,14),new THREE.MeshBasicMaterial({color,depthTest:true,depthWrite:true,toneMapped:false}));control.position.set(x,-api.height/2+.025,.065);control.userData.noteAction=action;control.userData.highlightScale=false;const icon=textPlane(label,"#07111f",.024,.024,45);icon.position.z=.003;control.add(icon);content.add(control);controls.push(control);api.addControl(control);}
 function dispose(){drag=null;api.removeControls(new Set(controls));api.unregister(group,false);if(group){group.removeFromParent();group.traverse(o=>{o.geometry?.dispose?.();o.material?.map?.dispose?.();o.material?.dispose?.();});}group=content=state=null;controls=[];eventObjects=[];api.layout();}
 function selectEvent(index){if(!state?.events[index])return;state.selected=index;for(const item of eventObjects){const selected=item.index===index;item.mesh.scale.setScalar(selected?1.65:1);item.mesh.material.opacity=selected?1:.82;if(item.label)item.label.scale.setScalar(selected?1.12:1);}const e=state.events[index];api.message(`${e.rawStart}${e.rawEnd!==e.rawStart?`–${e.rawEnd}`:""} · ${e.label}${e.description?` · ${e.description}`:""}`);}
 function open(source){dispose();state=parse(source);group=new THREE.Group();group.name="chronos-3d-window";content=new THREE.Group();group.add(content);const L=layout(state,1000,false),xScale=api.width*.84,ySpan=api.height*.66,rowH=ySpan/L.totalRows;
  const dragSurface=new THREE.Mesh(new THREE.PlaneGeometry(api.width*.92,api.height*.78),new THREE.MeshBasicMaterial({colorWrite:false,transparent:true,opacity:0,depthTest:false,depthWrite:false}));dragSurface.position.z=-.045;dragSurface.userData.noteAction="chronos-drag";dragSurface.userData.highlightScale=false;dragSurface.userData.preserveOpacity=true;content.add(dragSurface);controls.push(dragSurface);api.addControl(dragSurface);
  const title=textPlane(`Timeline · ${state.events.length} events`,"#f4f7ff",api.width*.62,.044,31);title.position.set(0,api.height/2-.027,.04);content.add(title);
  const gridMaterial=new THREE.MeshBasicMaterial({color:0x89a9d2,transparent:true,opacity:.16,depthTest:true,depthWrite:false,toneMapped:false});for(let tick=0;tick<=5;tick+=1){const gx=-xScale/2+xScale*tick/5,line=new THREE.Mesh(new THREE.BoxGeometry(.0014,ySpan,.002),gridMaterial);line.position.set(gx,0,-.03);line.raycast=()=>{};content.add(line);const date=textPlane(yearLabel(state.min+(state.max-state.min)*tick/5),"#aebed3",.072,.022,25,false);date.position.set(gx,-ySpan/2-.018,-.018);content.add(date);}for(let row=0;row<=L.totalRows;row+=1){const gy=ySpan/2-row*rowH,line=new THREE.Mesh(new THREE.BoxGeometry(xScale,.0012,.002),gridMaterial);line.position.set(0,gy,-.03);line.raycast=()=>{};content.add(line);}
  let offset=0;for(const name of L.groups){const rows=L.groupRows.get(name)||1,groupTop=ySpan/2-offset*rowH;for(const [index,e] of state.events.entries()){if(e.group!==name)continue;const row=L.assignments.get(index)||0,y=groupTop-(row+.5)*rowH,x1=(L.x(e.start)/1000-.5)*xScale,x2=(L.x(e.end)/1000-.5)*xScale,color=new THREE.Color(e.color);let mesh;if(e.type==="="){mesh=new THREE.Mesh(new THREE.BoxGeometry(.004,Math.max(.025,rowH*.7),.008),new THREE.MeshBasicMaterial({color,transparent:true,opacity:.82,toneMapped:false}));mesh.position.set(x1,y,0);}else if(e.type==="@"||e.end>e.start+.00001){const width=Math.max(.012,x2-x1);mesh=new THREE.Mesh(new THREE.BoxGeometry(width,.011,e.type==="@"?.008:.014),new THREE.MeshBasicMaterial({color,transparent:true,opacity:e.type==="@"?.42:.82,toneMapped:false}));mesh.position.set((x1+x2)/2,y,e.type==="@"?-.012:.006);}else{mesh=new THREE.Mesh(new THREE.SphereGeometry(.009,10,7),new THREE.MeshBasicMaterial({color,transparent:true,opacity:.86,toneMapped:false}));mesh.position.set(x1,y,.012);}mesh.userData.noteAction=`chronos-event:${index}`;mesh.userData.highlightScale=false;content.add(mesh);controls.push(mesh);api.addControl(mesh);const label=textPlane(e.label,"#eef5ff",Math.min(.19,Math.max(.07,e.label.length*.0065)),.026,27);label.position.set(Math.min(x1+.01,api.width*.38),y+Math.max(.018,rowH*.22),.028);content.add(label);eventObjects.push({index,mesh,label});}offset+=rows;}
  addControl("chronos-reset",0,"↺",0xffd166);addControl("chronos-close",api.width/2-.028,"×",0xff6b6b);api.register(group,api.width);api.message(`3D timeline ready · ${state.events.length} events. Pinch and drag to rotate.`);}
 function beginDrag(event){if(!state||!group)return false;const point=api.pinchPoint?.(event.frame,event.inputSource);if(!point)return false;drag={source:event.inputSource,point:group.worldToLocal(point.clone())};return true;}
 function endDrag(source){if(drag?.source===source)drag=null;}
 function update(_time,frame){if(!drag||!frame||!content)return;const point=api.pinchPoint?.(frame,drag.source);if(!point){drag=null;return;}const local=group.worldToLocal(point.clone()),dx=local.x-drag.point.x,dy=local.y-drag.point.y;content.rotation.y+=dx*7;content.rotation.x=THREE.MathUtils.clamp(content.rotation.x-dy*7,-1.15,1.15);drag.point.copy(local);}
 function handle(action){if(action==="chronos-drag")return true;if(action==="chronos-close"){dispose();api.message("Timeline closed.");return true;}if(action==="chronos-reset"){content.rotation.set(0,0,0);return true;}if(action.startsWith("chronos-event:")){selectEvent(Number(action.slice(14)));return true;}return false;}
 return{parse,layout,drawPreview,renderBlocks,open,dispose,handle,beginDrag,endDrag,update};
}
